say "Por que: uma consulta trivial leva 459ms hoje, medida pelo /api/health."
say "Uma tela faz 5 a 10 delas, o que dá os 3 segundos por clique."
say ""
step "Precisa ter: supabase CLI, psql, e o Docker rodando."
if [ "$ENSAIO" = "1" ]; then
  confirm "Pode começar o ensaio?"
else
  confirm "A equipe está avisada e é uma boa hora para o sistema cair?"
fi

command -v psql >/dev/null || { say "psql não encontrado. Instale o postgresql-client."; exit 1; }
docker info >/dev/null 2>&1 || { say "Docker não está rodando — o dump precisa dele."; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
DUMP_DIR="$(pwd)/.migracao-supabase"
REUSAR=0
if [ -s "$DUMP_DIR/schema.sql" ] && [ -s "$DUMP_DIR/data.sql" ]; then
  # Esta etapa só existe quando há dump anterior, então entra na conta aqui
  # em vez de deixar o rodapé prometer um total que não bate.
  TOTAL_STAGES=$((TOTAL_STAGES + 1))
  stage "Dump anterior encontrado"
  say "Já existe um dump nesta pasta, de uma execução anterior:"
  say ""
  ls -lh "$DUMP_DIR"/*.sql 2>/dev/null | awk '{print "   " $9 "  " $5}'
  say ""
  say "Reaproveitar pula as etapas 2, 3 e 4 — que é onde você já passou"
  say "quatro vezes. Só não reaproveite se a produção mudou desde então."
  say ""
  if confirm "Reaproveitar este dump?"; then
    REUSAR=1

    # Reaproveitar só é seguro se os logins estiverem cobertos. Sem isto, o
    # restore roda inteiro e ninguém consegue entrar depois — e isso só
    # aparece na virada, que é tarde demais para descobrir.
    if [ -s "$DUMP_DIR/auth.sql" ]; then
      AUTH_FILE="$DUMP_DIR/auth.sql"
      say "auth.sql presente — os logins estão cobertos."
    elif grep -qE 'COPY "?auth"?\."?users"?' "$DUMP_DIR/data.sql" 2>/dev/null; then
      say "Os logins estão dentro do data.sql."
    else
      say ""
      say "Este dump NÃO tem os logins — nem auth.sql, nem dentro do data.sql."
      say "Restaurar assim deixaria todo mundo sem entrar."
      say ""
      say "Só falta isso. Preciso da conexão do projeto ATUAL uma vez,"
      say "e faço só o dump do auth — segundos, não o dump inteiro."
      say ""
      while :; do
        ask_secret OLD_DB_URL "Cole a connection string do projeto ATUAL:"
        reject_direct "$OLD_DB_URL" && break
      done
      if dump_auth "$OLD_DB_URL"; then
        AUTH_FILE="$DUMP_DIR/auth.sql"
        say "Logins capturados: $(grep -cE "^[0-9a-f-]{36}\\t" "$DUMP_DIR/auth.sql" || echo '?') conta(s)."
      else
        say ""
        say "Não consegui capturar os logins. PARANDO — seguir daqui"
        say "deixaria todo mundo sem entrar, e só apareceria na virada."
        exit 1
      fi
    fi
    pause
  fi
fi

if [ "$REUSAR" = "0" ]; then
stage "Conexão do projeto ATUAL"
say "Vamos pegar a string de conexão do projeto que existe hoje."
open_url "https://supabase.com/dashboard/project/wntrsavneabdcrztwudf/settings/database"
step "Abra Connect e, no seletor do topo, escolha SESSION POOLER."
step "Não use Direct connection: ela é IPv6 e o Docker não alcança."
step "Copie a URI inteira e troque [YOUR-PASSWORD] pela senha real do banco."
while :; do
  ask_secret OLD_DB_URL "Cole a connection string do projeto ATUAL:"
  reject_direct "$OLD_DB_URL" && break
done

say ""
say "Testando a conexão..."
psql "$OLD_DB_URL" -c 'select 1' >/dev/null 2>&1 \
  || { say "Não consegui conectar. Confira a senha e tente de novo."; exit 1; }
say "Conectou."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if [ "$REUSAR" = "0" ]; then
stage "Dump: papéis, schema e dados"
say "Três arquivos, na ordem que o restore vai precisar."
mkdir -p "$DUMP_DIR"
say "Salvando em $DUMP_DIR"
say ""

step "1/3 papéis..."
npx supabase db dump --db-url "$OLD_DB_URL" -f "$DUMP_DIR/roles.sql" --role-only
step "2/3 schema..."
npx supabase db dump --db-url "$OLD_DB_URL" -f "$DUMP_DIR/schema.sql"
step "3/3 dados..."
npx supabase db dump --db-url "$OLD_DB_URL" -f "$DUMP_DIR/data.sql" --use-copy --data-only \
  -x "storage.buckets_vectors" -x "storage.vector_indexes"

say ""
say "Tamanhos:"
ls -lh "$DUMP_DIR"/*.sql | awk '{print "   " $9 "  " $5}'

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Verificar se os logins vieram junto"
say "A documentação do Supabase NÃO afirma que auth.users entra no dump."
say "É a diferença entre todo mundo manter o login e ninguém entrar."
say "Então conferimos agora, antes de qualquer passo irreversível."
say ""

# `grep -c` imprime 0 e sai com 1 quando não acha nada, então o `|| echo 0`
# que estava aqui produzia "0\n0" — o teste numérico quebrava, o `if` caía no
# else, e a mensagem dizia "os logins estão no dump" quando não estavam.
# A checagem escrita para evitar o desastre falhava ABERTA.
# O dump escreve `COPY "auth"."users"` — com aspas ENTRE as partes. Procurar
# por `auth\.users` não casa, e foi assim que eu concluí que os logins não
# vinham no dump quando vinham desde sempre, e depois montei um segundo dump
# que colidiu por chave duplicada.
AUTH_IN_DATA=$(grep -cE 'COPY "?auth"?\."?users"?' "$DUMP_DIR/data.sql" 2>/dev/null || true)
LIVE_USERS=$(psql "$OLD_DB_URL" -tAc 'select count(*) from auth.users' 2>/dev/null | tr -d ' ' || true)

say "  usuários no banco atual : ${LIVE_USERS:-?}"
say "  auth.users no data.sql  : ${AUTH_IN_DATA:-0}"
say ""

if [ "${AUTH_IN_DATA:-0}" -gt 0 ] 2>/dev/null; then
  say "Os logins vieram no dump principal."
  pause
else
  say "O dump principal NÃO traz os logins — confirmado, não suposto."
  say "Fazendo um dump do schema auth agora."
  say ""
  if dump_auth "$OLD_DB_URL"; then
    AUTH_FILE="$DUMP_DIR/auth.sql"
    say "Logins capturados — auth.sql entra no restore."
  else
    say ""
    say "Não consegui capturar os logins. PARANDO — seguir daqui deixaria"
    say "todo mundo sem entrar, e só apareceria na virada."
    exit 1
  fi
  pause
fi

fi

